/**
 * Node canvas on the site: a support team's morning digest as a flow of six steps, with the last connection (the
 * decision's No to Post the digest) left for you to draw. A premium element: this example is free
 * to read, the element installs with FoundKeep Pro.
 */
import {
  NodeCanvas,
  NodeCanvasNumber,
  NodeCanvasPair,
  NodeCanvasSegmented,
  NodeCanvasSelect,
  NodeCanvasSwitch,
  type NodeCanvasEdge,
  type NodeCanvasKind,
  type NodeCanvasNode,
} from "@/components/application/premium/node-canvas";

const KINDS: Record<string, NodeCanvasKind> = {
  trigger: { label: "Schedule", color: "#2f6bff", darkColor: "#7ea2ff", inputs: [], icon: ["M8 4.75V8l2 1.5", "M2.5 8a5.5 5.5 0 1 0 11 0a5.5 5.5 0 1 0-11 0"] },
  fetch: { label: "Fetch", color: "#0e8a78", darkColor: "#45c9b2", icon: ["M8 2.75v6.5M5.25 6.75 8 9.5l2.75-2.75", "M2.75 10v2.25c0 .55.45 1 1 1h8.5c.55 0 1-.45 1-1V10"] },
  summarise: { label: "Summarise", color: "#7a3ff2", darkColor: "#b496ff", icon: ["M3 4.25h10M3 8h10M3 11.75h6"] },
  decide: { label: "Decide", color: "#bf7400", darkColor: "#f0b04a", outputs: ["yes", "no"], portLabels: { yes: "Yes", no: "No" }, icon: ["M2.5 8h3.5l2.5-3.75h5M6 8l2.5 3.75h5"] },
  notify: { label: "Notify", color: "#d43d5c", darkColor: "#ff8098", outputs: [], icon: ["M4.25 11.25V7.5a3.75 3.75 0 0 1 7.5 0v3.75l1.25 1.25H3z", "M6.75 13.75h2.5"] },
};

const OPTIONS = {
  runs: ["Every weekday at 9:00", "Every hour", "When a ticket arrives"],
  from: ["Support inbox", "Billing inbox", "All inboxes"],
  group: ["Topic", "Customer", "Priority"],
  when: ["Any ticket is urgent", "3 or more are urgent", "Someone waits over 4 hours"],
  to: ["On-call pager", "Team channel", "Email to leads"],
};

// x and y run the flow left to right; vx and vy are where each step sits when a narrow canvas runs it top to bottom.
const STEPS: NodeCanvasNode[] = [
  { id: "schedule", kind: "trigger", title: "Weekday mornings", x: 0, y: 140, vx: 120, vy: 0, data: { runs: OPTIONS.runs[0] } },
  { id: "fetch", kind: "fetch", title: "Fetch open tickets", x: 280, y: 140, vx: 120, vy: 120, data: { from: OPTIONS.from[0], limit: 50 } },
  { id: "summary", kind: "summarise", title: "Summarise the queue", x: 560, y: 140, vx: 120, vy: 240, data: { length: "Short", group: OPTIONS.group[0] } },
  { id: "decide", kind: "decide", title: "Anything urgent?", x: 840, y: 140, vx: 120, vy: 360, data: { when: OPTIONS.when[0] } },
  { id: "page", kind: "notify", title: "Page the on-call", x: 1120, y: 20, vx: 0, vy: 500, data: { to: OPTIONS.to[0], quiet: false } },
  { id: "post", kind: "notify", title: "Post the digest", x: 1120, y: 260, vx: 240, vy: 500, data: { to: OPTIONS.to[1], quiet: true } },
];

const LINKS: NodeCanvasEdge[] = [
  { id: "e1", from: "schedule", fromPort: "out", to: "fetch", toPort: "in" },
  { id: "e2", from: "fetch", fromPort: "out", to: "summary", toPort: "in" },
  { id: "e3", from: "summary", fromPort: "out", to: "decide", toPort: "in" },
  { id: "e4", from: "decide", fromPort: "yes", to: "page", toPort: "in" },
];

type Settings = Record<string, string | number | boolean>;
const settingsOf = (step: NodeCanvasNode) => (step.data ?? {}) as Settings;

/** The line under each step's title, from its settings. */
function describe(step: NodeCanvasNode) {
  const s = settingsOf(step);
  switch (step.kind) {
    case "trigger":
      return String(s.runs);
    case "fetch":
      return `${s.from}, up to ${s.limit}`;
    case "summarise":
      return `${s.length}, grouped by ${String(s.group).toLowerCase()}`;
    case "decide":
      return String(s.when);
    default:
      return s.quiet ? `${s.to}, quiet at night` : String(s.to);
  }
}

export default function NodeCanvasDemo() {
  return (
    <div style={{ width: "100%", height: 600 }}>
      <NodeCanvas
        title="Support morning digest"
        nodes={STEPS}
        edges={LINKS}
        kinds={KINDS}
        defaultSelected="decide"
        describe={describe}
        inspector={(step, update) => {
          const s = settingsOf(step);
          const set = (key: string, value: string | number | boolean) => update({ data: { ...s, [key]: value } });
          const choose = (label: string, key: keyof typeof OPTIONS) => <NodeCanvasSelect label={label} value={String(s[key])} options={OPTIONS[key]} onChange={(v) => set(key, v)} />;
          switch (step.kind) {
            case "trigger":
              return choose("Runs", "runs");
            case "fetch":
              return (
                <NodeCanvasPair>
                  {choose("From", "from")}
                  <NodeCanvasNumber label="Up to" value={Number(s.limit)} min={10} max={200} step={10} onChange={(v) => set("limit", v)} />
                </NodeCanvasPair>
              );
            case "summarise":
              return (
                <>
                  <NodeCanvasSegmented label="Length" value={String(s.length)} options={["Short", "Medium", "Long"]} onChange={(v) => set("length", v)} />
                  {choose("Group by", "group")}
                </>
              );
            case "decide":
              return choose("Urgent when", "when");
            default:
              return (
                <>
                  {choose("Send to", "to")}
                  <NodeCanvasSwitch label="Quiet at night" checked={Boolean(s.quiet)} onChange={(v) => set("quiet", v)} />
                </>
              );
          }
        }}
      />
    </div>
  );
}

